function dre_url($key,$lang=null){$lang=$lang?:dre_lang();$routes=get_option('dre_routes',[]);return home_url($routes[$lang][$key]??($routes['ru'][$key]??'/'));}
function dre_asset($name){return get_template_directory_uri().'/assets/'.$name;}
function dre_pages($kind,$limit=-1){return get_posts(['post_type'=>['page','post'],'posts_per_page'=>$limit,'orderby'=>$kind==='blog'?'date':'menu_order date','order'=>$kind==='blog'?'DESC':'ASC','meta_query'=>[['key'=>'_dre_kind','value'=>$kind],['key'=>'_dre_lang','value'=>dre_lang()]]]);}
function dre_services(){return dre_pages('service');}
function dre_photo($post){return get_the_post_thumbnail_url($post,'large')?:dre_asset('clinic.jpg');}
function dre_lang_switch(){ $key=is_singular()?get_post_meta(get_queried_object_id(),'_dre_key',true):'home';$routes=get_option('dre_routes',[]);echo '<div class="language-switch" aria-label="Language">';foreach(['lv'=>'LV','ru'=>'RU','en'=>'EN'] as $lang=>$label){$path=$routes[$lang][$key]??($routes[$lang][get_post_type()==='post'?'blog':'home']??'/');echo '<a lang="'.$lang.'" class="'.(dre_lang()===$lang?'current':'').'" href="'.esc_url(home_url($path)).'"'.(dre_lang()===$lang?' aria-current="true"':'').'>'.$label.'</a>';}echo '</div>';}
function dre_book($label=null,$class='',$service='',$doctor=''){echo '<button type="button" class="button '.esc_attr($class).'" data-book data-service="'.esc_attr($service).'" data-doctor="'.esc_attr($doctor).'">'.esc_html($label?:dre_t('book')).dre_icon().'</button>';}
function dre_section_header($eyebrow,$title,$link_key=null,$link_label=null){echo '<div class="section-head"><div><div class="eyebrow">'.esc_html($eyebrow).'</div><h2>'.wp_kses_post($title).'</h2></div>';if($link_key)echo '<a class="text-link" href="'.esc_url(dre_url($link_key)).'">'.esc_html($link_label).dre_icon().'</a>';echo '</div>';}
function dre_service_cards(){foreach(dre_services() as $n=>$service){$has=get_post_thumbnail_id($service);echo '<a class="service-card '.(!$has?'no-photo':'').'" href="'.esc_url(get_permalink($service)).'"><div class="service-card-top"><div><span class="service-number">'.sprintf('%02d',$n+1).'</span><h3>'.esc_html(get_the_title($service)).'</h3><p>'.esc_html(get_the_excerpt($service)).'</p></div><span class="circle-arrow">'.dre_icon().'</span></div>';if($has){echo '<div class="service-image">'.get_the_post_thumbnail($service,'large',['loading'=>'lazy','alt'=>get_post_meta($service->ID,'_dre_service_alt',true)?:get_the_title($service)]).'<span class="service-card-caption">'.esc_html(dre_e('service_illustration')).'</span></div>';}else{$implant=get_post_meta($service->ID,'_dre_key',true)==='service_implants';echo '<div class="service-image service-illustration"><svg viewBox="0 0 100 100" fill="none" stroke="currentColor" stroke-width="1.1" aria-hidden="true">';echo $implant?'<path d="M32 15c-3-12 9-13 18-8 9-5 21-4 18 8l-4 16H36l-4-16Zm6 23h24l-6 46-6 7-6-7-6-46Zm0 9 24-6m-23 16 22-6m-21 16 20-6m-18 16 16-6"/>':'<path d="M24 23C20 3 37 5 50 12 63 5 80 3 76 23c-3 14-4 51-15 57-7 3-6-25-11-25s-4 28-11 25c-11-6-12-43-15-57Z"/><path d="M36 18c6-1 8 3 14 3"/>';echo '</svg></div>';}echo '</a>';}}
function dre_doctor_card($doctor){dre_render_doctor_card($doctor);}
function dre_doctor_role($id){$roles=get_post_meta($id,'_dre_roles',true);return is_array($roles)?($roles[dre_lang()]??$roles['ru']):get_post_meta($id,'_dre_role',true);}
function dre_blog_cards($limit=3){$posts=dre_pages('blog',$limit);if(!$posts){echo '<p>'.esc_html(dre_t('blog')).'</p>';return;}foreach($posts as $p){echo '<article class="blog-card"><a href="'.esc_url(get_permalink($p)).'"><div class="blog-image"><img src="'.esc_url(dre_photo($p)).'" alt="'.esc_attr(get_the_title($p)).'" loading="lazy"></div></a><div class="blog-meta"><span>DR. EVALD</span><time datetime="'.esc_attr(get_the_date('c',$p)).'">'.esc_html(get_the_date('d.m.Y',$p)).'</time></div><h3><a href="'.esc_url(get_permalink($p)).'">'.esc_html(get_the_title($p)).'</a></h3><a class="text-link" href="'.esc_url(get_permalink($p)).'">'.esc_html(dre_t('read')).dre_icon().'</a></article>';}}
function dre_sidebar(){echo '<aside><div class="sidebar-box"><h3>'.esc_html(dre_t('questions')).'</h3><p>'.esc_html(dre_t('sidebar_copy')).'</p>';dre_book();echo '<a class="sidebar-phone" href="tel:+37122004040">+371 22 004 040</a><span class="sidebar-hours">'.esc_html(dre_t('hours')).'</span><div class="side-services">';foreach(dre_services() as $p)echo '<a href="'.esc_url(get_permalink($p)).'">'.esc_html(get_the_title($p)).'</a>';echo '</div></div></aside>';}
function dre_booking_form($context='modal',$service='',$doctor=''){get_template_part('template-parts/booking-form',null,['context'=>$context,'service'=>$service,'doctor'=>$doctor]);}
function dre_cta(){$service=get_post_meta(get_queried_object_id(),'_dre_kind',true)==='service'?get_the_title(get_queried_object_id()):'';$doctor=get_post_type(get_queried_object_id())==='dre_doctor'&&get_post_meta(get_queried_object_id(),'_dre_group',true)!=='administration'?get_the_title(get_queried_object_id()):'';echo '<section class="cta-section" id="appointment"><div class="container cta-inner cta-with-form"><div class="cta-copy"><h2 id="cta-heading">'.wp_kses_post(dre_t('cta_heading')).'</h2><p>'.esc_html(dre_t('cta_copy')).'</p></div>';dre_booking_form('inline',$service,$doctor);echo '</div></section>';}
add_filter('language_attributes',function($out){return 'lang="'.esc_attr(['ru'=>'ru','lv'=>'lv','en'=>'en'][dre_lang()]).'"';});
add_filter('document_title_parts',function($parts){if(is_singular()){$title=get_post_meta(get_queried_object_id(),'_dre_seo_title',true);if($title)return ['title'=>$title];}return $parts;});
add_filter('the_content',function($content){return preg_replace('/\[\/?(?:vc_[^\]]*|gallery[^\]]*|contact-form-7[^\]]*)\]/','',$content);},5);

